import{_ as n,a0 as d,w as l,s as c,I as i,x as s,a1 as a,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"在 Arch Linux 上安裝 Docker | LCTT x X-CMD","titleTemplate":false,"description":"在 Arch Linux 上安裝 Docker | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Arch Linux 上安裝 Docker | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Arch Linux 上安裝 Docker | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20231030 Install Docker on Arch Linux","title":"在 Arch Linux 上安裝 Docker","tag":"202311","desc":""},"relativePath":"202311/20231030 Install Docker on Arch Linux.md","filePath":"[post].md"}'),p={name:"202311/20231030 Install Docker on Arch Linux.md"};function k(h,e,u,g,b,m){const o=d("Link");return l(),c("div",null,[e[25]||(e[25]=i("h1",{id:"在-arch-linux-上安裝-docker",tabindex:"-1"},[s("在 Arch Linux 上安裝 Docker "),i("a",{class:"header-anchor",href:"#在-arch-linux-上安裝-docker","aria-label":"Permalink to “在 Arch Linux 上安裝 Docker”"},"​")],-1)),e[26]||(e[26]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202311/09/154128mctmdkdd0jolyv0k.png",alt:""})],-1)),e[27]||(e[27]=i("blockquote",null,[i("p",null,"瞭解如何在 Arch Linux 上安裝 Docker，並使用 Docker Compose 和製表符補全為運行容器做好準備。")],-1)),i("p",null,[e[1]||(e[1]=s("在 Arch Linux 上安裝 Docker 很簡單。它可以在 Extra 倉庫中找到，你可以簡單地 ",-1)),a(o,{href:"https://itsfoss.com/pacman-command/"},{default:t(()=>[...e[0]||(e[0]=[s("執行 pacman 魔法",-1)])]),_:1}),e[2]||(e[2]=s("：",-1))]),e[28]||(e[28]=r('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S docker</span></span></code></pre></div><p>但要在 Arch Linux 上正確運行 Docker，還需要執行更多步驟。</p><h3 id="讓-arch-docker-做好準備" tabindex="-1">讓 Arch Docker 做好準備 <a class="header-anchor" href="#讓-arch-docker-做好準備" aria-label="Permalink to “讓 Arch Docker 做好準備”">​</a></h3><p>這一切都歸結為以下步驟：</p><ul><li>從 Arch 倉庫安裝 Docker</li><li>啓動 Docker 守護進程並在每次啓動時自動運行</li><li>將用户添加到 <code>docker</code> 組以運行 <code>docker</code> 命令而無需 <code>sudo</code></li></ul><p>讓我們看看詳細步驟。</p><h4 id="步驟-1-安裝-docker-包" tabindex="-1">步驟 1：安裝 Docker 包 <a class="header-anchor" href="#步驟-1-安裝-docker-包" aria-label="Permalink to “步驟 1：安裝 Docker 包”">​</a></h4><p>打開終端並使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S docker</span></span></code></pre></div><p>輸入密碼並在詢問時按 <code>Y</code>。</p><p><img src="https://itsfoss.com/content/images/2023/10/installing-docker-arch-linux.png" alt=""></p><p>這可能需要一些時間，具體取決於你使用的鏡像。</p><blockquote><p>💡 如果你看到找不到包或 404 錯誤，那麼你的同步資料庫可能是舊的。使用以下命令更新系統（它將下載大量軟件包並需要時間）： <code>sudo pacman -Syu</code></p></blockquote><h4 id="步驟-2-啓動-docker-守護進程" tabindex="-1">步驟 2：啓動 docker 守護進程 <a class="header-anchor" href="#步驟-2-啓動-docker-守護進程" aria-label="Permalink to “步驟 2：啓動 docker 守護進程”">​</a></h4><p>Docker 已安裝但未運行。你應該在<strong>第一次運行 Docker 命令</strong>之前啓動 Docker 守護進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start docker.service</span></span></code></pre></div><p>我還建議啓用 Docker 服務，以便 Docker 守護進程在系統啓動時自動啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable docker.service</span></span></code></pre></div><p>這樣，你就可以開始運行 <code>docker</code> 命令了。你不再需要手動啓動 Docker 服務。</p><p><img src="https://itsfoss.com/content/images/2023/10/start-docker-daemon-arch-linux.png" alt=""></p><h4 id="步驟-3-將用户添加到-docker-組" tabindex="-1">步驟 3：將用户添加到 docker 組 <a class="header-anchor" href="#步驟-3-將用户添加到-docker-組" aria-label="Permalink to “步驟 3：將用户添加到 docker 組”">​</a></h4><p>Docker 已安裝並且 Docker 服務正在運行。你幾乎已準備好運行 <code>docker</code> 命令。</p><p>但是，默認情況下，你需要將 <code>sudo</code> 與 <code>docker</code> 命令一起使用。這很煩人。</p><p>為了避免在每個 <code>docker</code> 命令中使用 <code>sudo</code>，你可以將自己（或任何其他用户）添加到 <code>docker</code> 組，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -aG docker $USER</span></span></code></pre></div><p><strong>你必須註銷（或關閉終端）並重新登錄才能使上述更改生效。如果你不想這樣做，請使用以下命令：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>newgrp docker</span></span></code></pre></div><p>現在已經準備好了。我們來測試一下。</p><h4 id="步驟-4-驗證-docker-安裝" tabindex="-1">步驟 4：驗證 docker 安裝 <a class="header-anchor" href="#步驟-4-驗證-docker-安裝" aria-label="Permalink to “步驟 4：驗證 docker 安裝”">​</a></h4><p>Docker 本身提供了一個很小的 Docker 鏡像來測試 Docker 安裝。運行它並查看是否一切正常：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker run hello-world</span></span></code></pre></div><p>你應該看到類似這樣的輸出，表明 Docker 成功運行：</p><p><img src="https://itsfoss.com/content/images/2023/10/docker-running-successfully-arch-linux.png" alt=""></p><p>恭喜！ 你已經在 Arch Linux 上成功安裝了 Docker。</p><h3 id="可選-安裝-docker-compose" tabindex="-1">可選：安裝 Docker Compose <a class="header-anchor" href="#可選-安裝-docker-compose" aria-label="Permalink to “可選：安裝 Docker Compose”">​</a></h3><p>Docker Compose 已經成為 Docker 不可或缺的一部分。它允許你管理多個容器應用。</p>',36)),i("p",null,[e[4]||(e[4]=s("較早的經典 Compose 由 ",-1)),e[5]||(e[5]=i("code",null,"docker-compose",-1)),e[6]||(e[6]=s(" Python 軟件包提供。Docker 還將其移植到 Go 中，並通過 ",-1)),e[7]||(e[7]=i("code",null,"docker compose",-1)),e[8]||(e[8]=s(" 提供，但該軟件包附帶 ",-1)),a(o,{href:"https://www.docker.com/products/docker-desktop/"},{default:t(()=>[...e[3]||(e[3]=[s("Docker Desktop",-1)])]),_:1}),e[9]||(e[9]=s("。",-1))]),e[29]||(e[29]=r(`<p>在這個階段，我建議使用經典的 <code>docker-compose</code> 插件並使用以下命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S docker-compose</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/10/install-docker-compose.png" alt=""></p><h3 id="故障排除技巧" tabindex="-1">故障排除技巧 <a class="header-anchor" href="#故障排除技巧" aria-label="Permalink to “故障排除技巧”">​</a></h3><p>以下是你可能遇到的一些常見問題以及可能的解決方案：</p><h4 id="製表符補全不適用於-docker-子命令" tabindex="-1">製表符補全不適用於 docker 子命令 <a class="header-anchor" href="#製表符補全不適用於-docker-子命令" aria-label="Permalink to “製表符補全不適用於 docker 子命令”">​</a></h4><p>如果你想對 <code>docker</code> 命令選項使用製表符補全（例如將 <code>im</code> 補全到 <code>images</code> 等），請安裝 <code>bash-completion</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S bash-completion</span></span></code></pre></div><p>關閉終端並啓動一個新終端。你現在應該能夠通過 <code>docker</code> 命令使用製表符補全功能。</p><h4 id="無法連接到-docker-守護進程錯誤" tabindex="-1">無法連接到 Docker 守護進程錯誤 <a class="header-anchor" href="#無法連接到-docker-守護進程錯誤" aria-label="Permalink to “無法連接到 Docker 守護進程錯誤”">​</a></h4><p>如果你看到以下錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker: Cannot connect to the Docker daemon at unix:///var/run/docker.sock. Is the docker daemon running?.</span></span>
<span class="line"><span>See &#39;docker run --help&#39;.</span></span></code></pre></div><p>那是因為 Docker 守護進程沒有運行。參考步驟 2，啓動 Docker 服務，確保其正在運行並啓用它，以便 Docker 守護進程在每次啓動時自動運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start docker.service</span></span>
<span class="line"><span>sudo systemctl enable docker.service</span></span></code></pre></div><h4 id="嘗試連接到-docker-守護程序套接字時權限被拒絕" tabindex="-1">嘗試連接到 Docker 守護程序套接字時權限被拒絕 <a class="header-anchor" href="#嘗試連接到-docker-守護程序套接字時權限被拒絕" aria-label="Permalink to “嘗試連接到 Docker 守護程序套接字時權限被拒絕”">​</a></h4><p>如果你看到此錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ddocker: permission denied while trying to connect to the Docker daemon socket at unix:///var/run/docker.sock: Post &quot;http://%2Fvar%2Frun%2Fdocker.sock/v1.24/containers/create&quot;: dial unix /var/run/docker.sock: connect: permission denied.</span></span>
<span class="line"><span>See &#39;docker run --help&#39;.</span></span></code></pre></div><p>這是因為你需要使用 <code>sudo</code> 運行 <code>docker</code> 命令，或者將用户添加到 <code>docker</code> 組以在不使用 <code>sudo</code> 的情況下運行 <code>docker</code> 命令。</p><p>我希望這篇簡短的文章可以幫助你在 Arch Linux 上運行 Docker。</p><p><em>（題圖：MJ/9951f8bf-d2e5-4335-bd86-ebf89cba654d）</em></p><hr>`,21)),i("p",null,[e[11]||(e[11]=s("via: ",-1)),a(o,{href:"https://itsfoss.com/install-docker-arch-linux/"},{default:t(()=>[...e[10]||(e[10]=[s("https://itsfoss.com/install-docker-arch-linux/",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=s("作者：",-1)),a(o,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...e[12]||(e[12]=[s("Abhishek Prakash",-1)])]),_:1}),e[17]||(e[17]=s(" 選題：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[13]||(e[13]=[s("lujun9972",-1)])]),_:1}),e[18]||(e[18]=s(" 譯者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:t(()=>[...e[14]||(e[14]=[s("geekpi",-1)])]),_:1}),e[19]||(e[19]=s(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:t(()=>[...e[15]||(e[15]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[22]||(e[22]=s("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[20]||(e[20]=[s("LCTT",-1)])]),_:1}),e[23]||(e[23]=s(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:t(()=>[...e[21]||(e[21]=[s("Linux中國",-1)])]),_:1}),e[24]||(e[24]=s(" 榮譽推出",-1))])])}const C=n(p,[["render",k]]);export{D as __pageData,C as default};
